-- Icône teintable. name = nom d'atlas, ou rbxassetid / id numérique.
local function Icon(parent, name, size, colorKey, z)
	local img = New("ImageLabel", {
		Name = "Icon",
		BackgroundTransparency = 1,
		Size = UDim2.fromOffset(size or 16, size or 16),
		ZIndex = z or 3,
		ScaleType = Enum.ScaleType.Fit,
		Parent = parent,
	})
	local function set(n)
		local r = IconRect[n]
		if r then
			img.Image = r[1]
			img.ImageRectOffset = r[2]
			img.ImageRectSize = Vector2.new(64, 64)
		elseif type(n) == "string" and (n:find("rbxasset") or n:find("rbxthumb")) then
			img.Image = n
			img.ImageRectSize = Vector2.zero
		elseif tonumber(n) then
			img.Image = "rbxassetid://" .. tostring(n)
			img.ImageRectSize = Vector2.zero
		end
	end
	set(name)
	if colorKey then Library:Register(img, { ImageColor3 = colorKey }) end
	return img, set
end
K.Icon = Icon

local function FxImage(parent, which, z)
	local r = Assets.FxRect[which]
	return New("ImageLabel", {
		BackgroundTransparency = 1,
		Image = Assets.Fx,
		ImageRectOffset = r[1],
		ImageRectSize = r[2],
		ZIndex = z or 1,
		Parent = parent,
	})
end
