	Library:Register(b, { BackgroundColor3 = "Element" })
	Corner(b, 7)
	local ic = Icon(b, icon, 16, "TextDim", (z or 22) + 1)
	ic.AnchorPoint = Vector2.new(0.5, 0.5)
