-- Animation d'une planche de sprites dans un ImageLabel.
local function SpriteSheet(img, sheet)
	if type(sheet) ~= "table" then return function() end end
	local cols = sheet.Columns or 1
	local frames = sheet.Frames or (cols * (sheet.Rows or 1))
	local fs = sheet.FrameSize or Vector2.new(256, 144)
	local fps = sheet.FPS or 15
	img.ImageRectSize = fs
	local t = 0
	return function(dt)
		t += dt
		local f = math.floor(t * fps) % frames
		img.ImageRectOffset = Vector2.new((f % cols) * fs.X, math.floor(f / cols) * fs.Y)
	end
end
K.SpriteSheet = SpriteSheet

function Library:CreateWindow(opts)
	opts = opts or {}
	if opts.Accent and (opts.ForceAccent or not Library.KeepAccent) then Library:SetAccent(opts.Accent) end
