	if opts.Effects ~= nil then Library.Effects = opts.Effects ~= false end
	if opts.Blur ~= nil then Library.Blur = opts.Blur ~= false end
	if opts.Mobile ~= nil then K.ApplyMetrics(opts.Mobile) else K.ApplyMetrics(K.DetectMobile()) end
	if opts.Scale then Library:SetScale(opts.Scale) end
	Library.WindowOptions = opts

	-- Intro plein écran (désactivable par le script ou par l'utilisateur).
	if opts.Intro ~= false and Prefs.Intro ~= false and not Library.IntroPlayed and Library.Intro then
		Library.IntroPlayed = true
