	local function savePlacement()
		if Library.Mobile then return end
		local vp = ViewportSize()
		local c = root.AbsolutePosition + root.AbsoluteSize / 2 - ScreenGui.AbsolutePosition
		Prefs.Positions = type(Prefs.Positions) == "table" and Prefs.Positions or {}
		Prefs.Positions[gk] = { px = c.X / vp.X, py = c.Y / vp.Y, w = root.Size.X.Offset, h = root.Size.Y.Offset }
		K.SavePrefs()
	end

	local dragging, dragStart, dragOrigin = false, nil, nil
	local locked = false
	function self:SetLocked(v) locked = v and true or false end
	local function beginDrag(input)
		if locked or Library.Mobile or not IsClick(input) then return end
		dragging = true
		dragStart = K.InputPos(input)
		local vp = ViewportSize()
		local c = root.AbsolutePosition + root.AbsoluteSize / 2 - ScreenGui.AbsolutePosition
		dragOrigin = c
		root.Position = UDim2.fromOffset(c.X, c.Y)
		local _ = vp
	end
	Library:Connect(topBar.InputBegan, beginDrag)
	Library:Connect(brand.InputBegan, beginDrag)
	Library:Connect(UserInputService.InputChanged, function(input)
		if not dragging or not IsMove(input) then return end
		local p = dragOrigin + (K.InputPos(input) - dragStart)
		local vp = ViewportSize()
		local half = root.AbsoluteSize / 2
		local gx, gy
		if Prefs.Snap ~= false then
			local SNAP = 14
			local cands = {
				{ math.abs(p.X - vp.X / 2), vp.X / 2, vp.X / 2 },
				{ math.abs(p.X - half.X - 12), half.X + 12, 12 },
				{ math.abs(p.X + half.X - (vp.X - 12)), vp.X - 12 - half.X, vp.X - 12 },
			}
			for _, cnd in ipairs(cands) do
				if cnd[1] < SNAP then p = Vector2.new(cnd[2], p.Y); gx = cnd[3]; break end
			end
			local candsY = {
				{ math.abs(p.Y - vp.Y / 2), vp.Y / 2, vp.Y / 2 },
				{ math.abs(p.Y - half.Y - 12), half.Y + 12, 12 },
				{ math.abs(p.Y + half.Y - (vp.Y - 12)), vp.Y - 12 - half.Y, vp.Y - 12 },
			}
			for _, cnd in ipairs(candsY) do
				if cnd[1] < SNAP then p = Vector2.new(p.X, cnd[2]); gy = cnd[3]; break end
			end
		end
		FX.Guide(1, gx)
		FX.Guide(2, gy)
		root.Position = UDim2.fromOffset(p.X, p.Y)
	end)
	Library:Connect(UserInputService.InputEnded, function(input)
		if dragging and IsClick(input) then
			dragging = false
			FX.Guide(1, nil)
			FX.Guide(2, nil)
			savePlacement()
		end
	end)

	local resizing, resizeStart, startSize = false, nil, nil
	Library:Connect(grip.InputBegan, function(input)
		if IsClick(input) and not locked then
			resizing = true
			resizeStart = K.InputPos(input)
			startSize = Vector2.new(root.Size.X.Offset, root.Size.Y.Offset)
			-- Ancrage en haut à gauche pendant le redimensionnement.
			local tl = root.AbsolutePosition - ScreenGui.AbsolutePosition
			root.AnchorPoint = Vector2.new(0, 0)
			root.Position = UDim2.fromOffset(tl.X, tl.Y)
		end
	end)
	Library:Connect(UserInputService.InputChanged, function(input)
		if resizing and IsMove(input) then
			local d = (K.InputPos(input) - resizeStart) / math.max(uiFactor, 0.01)
			root.Size = UDim2.fromOffset(math.clamp(startSize.X + d.X, 680, 1600), math.clamp(startSize.Y + d.Y, 440, 1000))
		end
	end)
	Library:Connect(UserInputService.InputEnded, function(input)
		if resizing and IsClick(input) then
			resizing = false
			local c = root.AbsolutePosition + root.AbsoluteSize / 2 - ScreenGui.AbsolutePosition
			root.AnchorPoint = Vector2.new(0.5, 0.5)
			root.Position = UDim2.fromOffset(c.X, c.Y)
			savePlacement()
		end
	end)

	function self:ResetLayout()
