	--=================================================================
	-- Recherche dans la page courante (Ctrl+F)
	--=================================================================

	function self:ApplySearch()
		local tab = self.ActiveTab
		local page = tab and tab.ActivePage
		if not page then return end
		local q = string.lower(searchBox.Text or "")
		for _, g in ipairs(page.Groups) do
			local any = false
			local titleHit = q ~= "" and string.find(string.lower(tostring(g.Name or "")), q, 1, true) ~= nil
			for _, r in ipairs(g.Rows) do
				local ok = q == "" or titleHit or string.find(r.Text, q, 1, true) ~= nil
				r.Frame.Visible = ok
				any = any or ok
			end
			g.Frame.Visible = q == "" or any or titleHit
		end
	end
	Library:Connect(searchBox:GetPropertyChangedSignal("Text"), function() self:ApplySearch() end)
	Library:Connect(searchBox.Focused, function() Paint(searchStroke, 0.15, "Color", "Accent") end)
	Library:Connect(searchBox.FocusLost, function() Paint(searchStroke, 0.15, "Color", "BorderSoft") end)

	--=================================================================
	-- Animation continue (menu ouvert seulement)
	--=================================================================

	local frames, acc, fps = 0, 0, 60
	Library:Connect(RunService.RenderStepped, function(dt)
		frames += 1
		acc += dt
		if acc >= 0.5 then
			fps = math.floor(frames / acc + 0.5)
			frames, acc = 0, 0
			if root.Visible then
				local ping = 0
				pcall(function() ping = math.floor(Stats.Network.ServerStatsItem["Data Ping"]:GetValue()) end)
				footerRight.Text = ('<font color="#%s">●</font>  %s  ·  %d FPS  ·  %d MS'):format(Theme.Success:ToHex(), statusText, fps, ping)
				for _, tab in ipairs(self.Tabs) do tab.CountLabel.Text = tostring(tab:CountRows()) end
			end
		end
		if root.Visible then stepBanner(dt) end
	end)

	--=================================================================
	-- Ouverture / fermeture
	--=================================================================

	local generation, cancelFx = 0, {}
	local lastToggle, transitionUntil = -math.huge, 0
	local minimized = false
	local fullSize

	local function cancelEffects()
		for _, c in ipairs(cancelFx) do pcall(c) end
		table.clear(cancelFx)
	end

	local function targetRect()
		local o = FxLayer.AbsolutePosition
		local center = root.AbsolutePosition + root.AbsoluteSize / 2 - o
		local w, h = root.Size.X.Offset * uiFactor, root.Size.Y.Offset * uiFactor
		return { x = center.X - w / 2, y = center.Y - h / 2, w = w, h = h }
	end

	local function reveal(quick)
		root.Visible = true
		veil.BackgroundTransparency = 0
		Tween(veil, quick and 0.18 or 0.4, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad)
		windowScale.Scale = uiFactor * (quick and 0.97 or 0.96)
		Tween(windowScale, quick and 0.25 or 0.5, { Scale = uiFactor }, Enum.EasingStyle.Exponential)
		local tab = self.ActiveTab
		if tab and tab.ActivePage and not quick then
			for i, g in ipairs(tab.ActivePage.Groups) do g:Animate(0.12 + (i - 1) * 0.05) end
		end
		if not quick then FX.Sweep(panel, 0.15, 0.9, 0.9) end
	end

	function self:SetOpen(state, instant)
		state = state and true or false
		Library.Open = state
		K.CloseActivePopup()
		if self.ToggleButton then self.ToggleButton.Visible = Library.Mobile or not state end

		-- Absolute zero blur guarantee
		FX.GameBlur(false)
		
		if state then
			K.Modal.Modal = true
			Library:ShowCursor(true)
			root.Visible = true
			veil.BackgroundTransparency = 1
			windowScale.Scale = uiFactor
			if not instant then Library:PlaySound("Open") end
			local tab = self.ActiveTab
			if tab and tab.ActivePage then
				for i, g in ipairs(tab.ActivePage.Groups) do g:Animate(0.08 + (i - 1) * 0.03) end
			end
		else
			K.Modal.Modal = false
			Library:ShowCursor(false)
			root.Visible = false
			veil.BackgroundTransparency = 1
			if not instant then Library:PlaySound("Close") end
		end
	end

	function self:Toggle() self:SetOpen(not Library.Open) end

	function self:SetMinimized(v)
		v = v and true or false
		if v == minimized or Library.Mobile then return end
		minimized = v
		if v then
			fullSize = root.Size
			contentHolder.Visible = false
			footerBar.Visible = false
			Tween(root, 0.35, { Size = UDim2.fromOffset(root.Size.X.Offset, M.TopBar) }, Enum.EasingStyle.Quint)
		else
			Tween(root, 0.35, { Size = fullSize or UDim2.fromOffset(780, 520) }, Enum.EasingStyle.Quint)
			task.delay(0.2 * Library.Motion, function()
				if not minimized then contentHolder.Visible = true; footerBar.Visible = true end
			end)
		end
		Library:PlaySound("Tab")
	end

	Library:Connect(closeBtn.MouseButton1Click, function() self:SetOpen(false) end)
	Library:Connect(closeBtn.MouseEnter, function() Paint(closeIcon, 0.12, "ImageColor3", "Danger") end)
	Library:Connect(minBtn.MouseButton1Click, function() self:SetMinimized(not minimized) end)
	Library:Connect(aiBtn.MouseButton1Click, function()
		Library:PlaySound("Click")
		if Library.OpenPalette then Library:OpenPalette() end
	end)
	local function openCustomize()
		Library:PlaySound("Click")
		if self.ToggleCustomize then self:ToggleCustomize() end
	end
	Library:Connect(custBtn.MouseButton1Click, openCustomize)
	Library:Connect(gearBtn.MouseButton1Click, openCustomize)

	function self:Unload() Library:Unload() end
	function self:Destroy() Library:Unload() end

	Library:Connect(UserInputService.InputBegan, function(input, processed)
		if input.KeyCode == Library.ToggleKey and not UserInputService:GetFocusedTextBox() then
			self:Toggle()
			return
		end
		if processed then return end
		local ctrl = UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
		if ctrl and input.KeyCode == Enum.KeyCode.F and Library.Open and search.Visible then
			task.defer(function() searchBox:CaptureFocus() end)
		end
	end)

