	local function moveHighlight(button, instant)
		task.defer(function()
			local f = math.max(windowScale.Scale, 0.01)
			local y = (button.AbsolutePosition.Y - sidebar.AbsolutePosition.Y) / f
			local w = mini and (M.SidebarMini - 20) or (M.Sidebar - 20)
			tabHighlight.Visible = true
			local d = instant and 0 or 0.32
			Tween(tabHighlight, d, { Position = UDim2.fromOffset(10, y), Size = UDim2.fromOffset(w, M.TabRow) }, Enum.EasingStyle.Quint)
			tabBar.Size = UDim2.fromOffset(3, 4)
			Tween(tabBar, 0.4, { Size = UDim2.fromOffset(3, 16) }, Enum.EasingStyle.Back, nil, 0.1)
		end)
	end
	Library:Connect(tabsList:GetPropertyChangedSignal("CanvasPosition"), function()
		if self.ActiveTab then moveHighlight(self.ActiveTab.Button, true) end
	end)

	function self:AddTab(name, icon)
		local button = New("TextButton", {
			Name = "Tab_" .. tostring(name),
			Text = "",
			AutoButtonColor = false,
			BackgroundTransparency = 1,
			Size = UDim2.new(1, 0, 0, M.TabRow),
			LayoutOrder = #self.Tabs + 1,
			ZIndex = 5,
			Parent = tabsList,
		})
		local iconName = icon
		if iconName == nil or iconName == "" then iconName = AutoIcon(name) end
		local iconGui
		if type(iconName) == "string" and not Library.IconNames[iconName] and #iconName <= 4 and not iconName:find("rbx") then
			iconGui = Label(button, iconName, 14, "TextFaint", Enum.FontWeight.Bold)
			iconGui.Size = UDim2.fromOffset(18, 18)
			iconGui.TextXAlignment = Enum.TextXAlignment.Center
		else
			iconGui = Icon(button, iconName, 17, "TextFaint", 6)
		end
		iconGui.AnchorPoint = Vector2.new(0, 0.5)
		iconGui.Position = UDim2.new(0, 10, 0.5, 0)
		iconGui.ZIndex = 6

		local label = Label(button, name, 13.5, "TextDim", Enum.FontWeight.Medium)
		label.Position = UDim2.fromOffset(38, 0)
		label.Size = UDim2.new(1, -70, 1, 0)
		label.TextTruncate = Enum.TextTruncate.AtEnd
		label.ZIndex = 6
		label.Visible = not mini

		local count = Mono(button, "0", 10, "TextFaint")
		count.AnchorPoint = Vector2.new(1, 0)
		count.Position = UDim2.new(1, -8, 0, 0)
		count.Size = UDim2.new(0, 26, 1, 0)
		count.TextXAlignment = Enum.TextXAlignment.Right
		count.ZIndex = 6
		count.Visible = not mini

		local content = New("Frame", {
			Name = "Content_" .. tostring(name),
			BackgroundTransparency = 1,
			Size = UDim2.fromScale(1, 1),
			Visible = false,
			Parent = contentHolder,
		})

		-- Onglets de page de l'en-tête, soulignés par un trait qui glisse.
		local pageBox = New("Frame", {
			Name = "PageBox_" .. tostring(name),
			BackgroundTransparency = 1,
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			Visible = false,
			ZIndex = 21,
			Parent = pagesHolder,
		})
		local pageRow = New("Frame", {
			Name = "PageRow",
			BackgroundTransparency = 1,
			Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X,
			ZIndex = 22,
			Parent = pageBox,
		})
		List(pageRow, 2, Enum.FillDirection.Horizontal, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)
		local underline = New("Frame", {
			Name = "Underline",
			AnchorPoint = Vector2.new(0, 1),
			Position = UDim2.new(0, 0, 1, 13),
			Size = UDim2.fromOffset(0, 2),
			BorderSizePixel = 0,
			ZIndex = 23,
			Parent = pageBox,
		})
		Library:Register(underline, { BackgroundColor3 = "Accent" })
		Corner(underline, "full")

		local tab = setmetatable({
			Name = name, Window = self, Button = button, Label = label, CountLabel = count,
			Content = content, PageRow = pageRow, PageBox = pageBox, PagesHolder = content, Pages = {},
			Icon = iconGui,
		}, Tab)

		function tab.RefreshPages()
			pageBox.Visible = (#tab.Pages > 1) and (self.ActiveTab == tab)
		end
		function tab.MoveUnderline(btn, instant)
			task.defer(function()
				local f = math.max(windowScale.Scale, 0.01)
				local x = (btn.AbsolutePosition.X - pageBox.AbsolutePosition.X) / f
				local w = btn.AbsoluteSize.X / f
				Tween(underline, instant and 0 or 0.35, { Position = UDim2.new(0, x + 10, 1, 13), Size = UDim2.fromOffset(math.max(w - 20, 6), 2) }, Enum.EasingStyle.Quint)
			end)
		end

		local hovering = false
		local function paint(active, instant)
			local d = instant and 0 or 0.15
			Paint(label, d, "TextColor3", (active or hovering) and "Text" or "TextDim")
			local ic = active and "Accent" or (hovering and "TextDim" or "TextFaint")
			Paint(iconGui, d, iconGui:IsA("ImageLabel") and "ImageColor3" or "TextColor3", ic)
			if active then moveHighlight(button, instant) end
		end
		tab.Paint = paint

		function tab:Select(silent)
			for _, other in ipairs(self.Window.Tabs) do
				if other ~= tab then
					other.Content.Visible = false
					other.PageBox.Visible = false
					other.Paint(false)
				end
			end
			self.Window.ActiveTab = tab
			content.Visible = true
			paint(true)
			tab.RefreshPages()
			updateCrumb()
			local p = tab.ActivePage or tab.Pages[1]
			if p then
				if tab.ActivePage == p then
					-- Rejoue l'entrée des colonnes et des groupes.
					p.Content.Visible = false
					tab.ActivePage = nil
				end
				p.Select(true)
			end
			if not silent then Library:PlaySound("Tab") end
		end

		Library:Connect(button.MouseButton1Click, function()
			if self.ActiveTab ~= tab then tab:Select() end
		end)
		Library:Connect(button.MouseEnter, function()
			hovering = true
			if self.ActiveTab ~= tab then paint(false) end
			if mini then Library:ShowTooltip(tostring(name)) end
		end)
		Library:Connect(button.MouseLeave, function()
			hovering = false
			if self.ActiveTab ~= tab then paint(false) end
			Library:HideTooltip()
		end)

		table.insert(self.Tabs, tab)
		if #self.Tabs == 1 then
			task.defer(function() if not self.ActiveTab then tab:Select(true) end end)
		end
		return tab
	end

	--=================================================================
	-- Bouton d'ouverture (mobile, ou sur demande)
	--=================================================================

	if opts.ToggleButton ~= false and (Library.Mobile or opts.ToggleButton) then
		local s2 = Library.Mobile and 48 or 40
		local btn = New("Frame", {
			Name = "ToggleButton",
			Size = UDim2.fromOffset(s2, s2),
			Position = opts.ToggleButtonPosition or UDim2.new(0, 14, 0.5, -60),
			ZIndex = 950,
			Parent = ScreenGui,
		})
		Library:Register(btn, { BackgroundColor3 = "Panel2" })
		Corner(btn, 12)
		Stroke(btn, "Border")
		Scalable(btn)
		local mark = New("ImageLabel", {
			BackgroundTransparency = 1,
			Image = Assets.Wordmark,
			ImageRectOffset = Vector2.new(Assets.WordmarkCells[1][1], 0),
			ImageRectSize = Vector2.new(Assets.WordmarkCells[1][2] - Assets.WordmarkCells[1][1], Assets.WordmarkSize.Y),
			AnchorPoint = Vector2.new(0.5, 0.5),
			Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromScale(0.62, 0.62),
			ScaleType = Enum.ScaleType.Fit,
			ZIndex = 951,
			Parent = btn,
		})
		Library:Register(mark, { ImageColor3 = "Text" })
		local moved, pressStart, btnStart = false, nil, nil
		local hh = Hit(btn, "ToggleHit", 952)
		Library:Connect(hh.InputBegan, function(input)
			if IsClick(input) then
				moved = false
				pressStart = K.InputPos(input)
				btnStart = btn.Position
			end
		end)
		Library:Connect(UserInputService.InputChanged, function(input)
			if not pressStart or not IsMove(input) then return end
			local d = K.InputPos(input) - pressStart
			if d.Magnitude > 6 then
				moved = true
				btn.Position = UDim2.new(btnStart.X.Scale, btnStart.X.Offset + d.X, btnStart.Y.Scale, btnStart.Y.Offset + d.Y)
			end
		end)
		Library:Connect(UserInputService.InputEnded, function(input)
			if not pressStart or not IsClick(input) then return end
			pressStart = nil
			if not moved then self:Toggle() end
		end)
		self.ToggleButton = btn
	end

	-- Première ouverture : après l'intro, sinon une fois les onglets construits.
	Library.Open = false
	task.defer(function()
		if Library.Unloaded then return end
		if Library.SplashActive then
			Library.PendingOpen = true
		elseif not Library.Open then
			self:SetOpen(true)
		end
	end)
	if K.OnWindow then for _, fn in ipairs(K.OnWindow) do task.spawn(fn, self) end end
	return self
end

--=====================================================================
-- Intro plein écran
-- Vidéo HD d'Aizen (webm servi par le site, lue en local par l'executor),
-- sinon la planche animée hébergée sur Roblox. Barres cinéma, étalonnage,
-- 鏡花水月, titre, voix ; puis l'écran se fend et vole en éclats.
--=====================================================================

local function RunIntro(opts, ctl)
	local scriptFx = ctl.ScriptFx

	-- La taille de l'écran n'est pas toujours définitive au lancement.
	local t00 = os.clock()
	local last = ViewportSize()
	repeat
		task.wait(0.05)
		local now = ViewportSize()
		local stable = (now - last).Magnitude < 1
		last = now
	until (stable and os.clock() - t00 > 0.15) or os.clock() - t00 > 0.6
	local vp = ViewportSize()
	local H = vp.Y
	local skipped, finished = false, false
	local manualDone = opts.Manual ~= true
	Library._IntroRelease = function() manualDone = true end
	-- Bouton d'ouverture touché pendant l'intro : on passe directement à la fin.
	-- (un SetOpen du script juste après CreateWindow n'arrive qu'avant 1,2 s : on l'ignore).
	local introStart = os.clock()
	Library._IntroSkip = function()
		if os.clock() - introStart > 1.2 then skipped = true end
	end

	local overlay = New("Frame", {
		Name = "Intro",
		BackgroundColor3 = Color3.fromRGB(4, 4, 6),
		BorderSizePixel = 0,
		Size = UDim2.fromScale(1, 1),
		Active = true,
		ZIndex = 800,
		Parent = ScreenGui,
	})
	ctl.Overlay = overlay
	local stage = New("Frame", {
		Name = "Stage", BackgroundTransparency = 1, ClipsDescendants = true,
		Size = UDim2.fromScale(1, 1), ZIndex = 801, Parent = overlay,
	})

	-- Image : vidéo si disponible, sinon planche de sprites.
	local media = New("Frame", {
		Name = "Media", BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
		Size = UDim2.fromScale(1, 1), ZIndex = 802, Parent = stage,
	})
	local mediaScale = New("UIScale", { Scale = 1.12, Parent = media })

	local function cover(w, h, zoom)
		local v = ViewportSize()
		local s = math.max(v.X / w, v.Y / h) * (zoom or 1)
		return UDim2.fromOffset(math.ceil(w * s), math.ceil(h * s))
	end
	local mediaW, mediaH, mediaZoom = 16, 9, 1

	local video, sprite, stepSprite
	local function useSprite()
		sprite = New("ImageLabel", {
			Name = "Sheet", BackgroundTransparency = 1, Image = Assets.Aizen,
			AnchorPoint = Vector2.new(0.5, 0.42), Position = UDim2.fromScale(0.5, 0.42),
			Size = cover(200, 123, 1.06), ImageTransparency = 1, ZIndex = 803, Parent = media,
		})
		mediaW, mediaH, mediaZoom = 200, 123, 1.06
		stepSprite = SpriteSheet(sprite, Library.DefaultBannerSheet)
	end

	local videoPath = opts.Media
	local fetched = videoPath ~= nil or Library.Mobile
	if Library.Mobile then videoPath = nil end
	if not fetched then
		task.spawn(function()
			videoPath = K.Media("intro.webm", 50000)
			fetched = true
		end)
	end
	-- Pendant le téléchargement : noir, filet lumineux, grondement.
	local t0 = os.clock()
	while not fetched and os.clock() - t0 < 2.5 and not skipped do task.wait() end
	if videoPath then
		local ok = pcall(function()
			video = New("VideoFrame", {
				Name = "Video", BackgroundTransparency = 1, Looped = false,
				Video = videoPath, Volume = 0,
				AnchorPoint = Vector2.new(0.5, 0.45), Position = UDim2.fromScale(0.5, 0.45),
				Size = cover(16, 9), ZIndex = 803, Parent = media,
			})
			-- PreloadAsync peut ne jamais rendre la main si la vidéo est illisible : délai borné.
			task.spawn(function() pcall(function() ContentProvider:PreloadAsync({ video }) end) end)
			local tl = os.clock()
			while not video.IsLoaded and os.clock() - tl < 1.5 and not skipped do task.wait() end
			local res = video.Resolution
			if res.X > 0 and res.Y > 0 then mediaW, mediaH = res.X, res.Y end
			video.Size = cover(mediaW, mediaH)
		end)
		if not ok or not (video and video.IsLoaded) then
			if video then video:Destroy() end
			video = nil
		end
	end
	if not video then useSprite() end

	-- Étalonnage : teinte d'accent, bas assombri, vignette, grain qui scintille.
	local tint = New("Frame", {
		BackgroundColor3 = Theme.AccentDim, BackgroundTransparency = 1,
		BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 804, Parent = stage,
	})
	local shade = New("Frame", {
		BackgroundColor3 = Color3.new(0, 0, 0), BackgroundTransparency = 1,
		BorderSizePixel = 0, Size = UDim2.fromScale(1, 1), ZIndex = 805, Parent = stage,
	})
	local shadeGrad = New("UIGradient", {
		Rotation = 90,
		Transparency = NSeq({ { 0, 0.55 }, { 0.35, 0.85 }, { 0.62, 0.55 }, { 1, 0.05 } }),
		Parent = shade,
	})
	local _ = shadeGrad
	local vig = FxImage(stage, "vignette", 806)
	vig.Size = UDim2.fromScale(1, 1)
	vig.ImageTransparency = 1
	local grain = New("ImageLabel", {
		BackgroundTransparency = 1, Image = Assets.Grain, ImageTransparency = 1,
		ScaleType = Enum.ScaleType.Tile, TileSize = UDim2.fromOffset(160, 160),
		Size = UDim2.new(1, 160, 1, 160), Position = UDim2.fromOffset(-80, -80),
		ZIndex = 807, Parent = stage,
	})

	-- Barres cinéma : fermées au départ (l'œil s'ouvre).
	local barH = math.floor(H * 0.1)
	local function bar(top)
		return New("Frame", {
			BackgroundColor3 = Color3.new(0, 0, 0), BorderSizePixel = 0,
			AnchorPoint = Vector2.new(0, top and 0 or 1),
			Position = UDim2.fromScale(0, top and 0 or 1),
			Size = UDim2.new(1, 0, 0.5, 1), ZIndex = 820, Parent = overlay,
		})
	end
	local barTop, barBottom = bar(true), bar(false)
	local seam = FxImage(overlay, "streak", 821)
	seam.AnchorPoint = Vector2.new(0.5, 0.5)
	seam.Position = UDim2.fromScale(0.5, 0.5)
	seam.Size = UDim2.fromOffset(0, 36)
	seam.ImageColor3 = Theme.Glass

	-- Bloc titre, en bas à gauche, comme un générique.
	local margin = math.floor(math.max(vp.X * 0.06, 28))
	local block = New("Frame", {
		Name = "Titles", BackgroundTransparency = 1,
		AnchorPoint = Vector2.new(0, 1), Position = UDim2.new(0, margin, 1, -barH - math.floor(H * 0.06)),
		Size = UDim2.fromOffset(math.min(vp.X - margin * 2, 900), math.floor(H * 0.42)),
		ZIndex = 830, Parent = overlay,
	})
	local kicker = Mono(block, "N W   H U B   P R E S E N T S", math.clamp(H * 0.014, 10, 15), "TextDim", Enum.FontWeight.SemiBold)
	kicker.Size = UDim2.new(1, 0, 0, math.floor(H * 0.03))
	kicker.Position = UDim2.fromOffset(2, 0)
	kicker.TextTransparency = 1
	kicker.ZIndex = 831

	local gh = math.floor(math.clamp(H * 0.12, 64, 150))
	local glyphs = {}
	local gx = 0
	for i, cell in ipairs(Assets.WordmarkCells) do
		local cw = cell[2] - cell[1]
		local w = math.floor(gh * cw / Assets.WordmarkSize.Y)
		local holder = New("Frame", {
			BackgroundTransparency = 1, Position = UDim2.fromOffset(gx, math.floor(H * 0.04)),
			Size = UDim2.fromOffset(w, gh), ZIndex = 832, Parent = block,
		})
		local glow = FxImage(holder, "glow", 832)
		glow.AnchorPoint = Vector2.new(0.5, 0.5)
		glow.Position = UDim2.fromScale(0.5, 0.5)
		glow.Size = UDim2.fromScale(2.2, 2.2)
		glow.ImageColor3 = Theme.Accent
		glow.ImageTransparency = 1
		local g = New("ImageLabel", {
			BackgroundTransparency = 1, Image = Assets.Wordmark,
			ImageRectOffset = Vector2.new(cell[1], 0), ImageRectSize = Vector2.new(cw, Assets.WordmarkSize.Y),
			AnchorPoint = Vector2.new(0.5, 0.5), Position = UDim2.fromScale(0.5, 0.5),
			Size = UDim2.fromScale(1, 1), ImageTransparency = 1, ZIndex = 833, Parent = holder,
		})
		local gs = New("UIScale", { Scale = 1.35, Parent = g })
		glyphs[i] = { Img = g, Scale = gs, Glow = glow }
		gx += w + math.floor(gh * 0.06)
	end

	local titleSize = math.floor(math.clamp(H * 0.062, 30, 76))
	local titleY = math.floor(H * 0.04) + gh + math.floor(H * 0.025)
	local titleRow = New("Frame", {
		BackgroundTransparency = 1, ClipsDescendants = true,
		Position = UDim2.fromOffset(0, titleY), Size = UDim2.new(1, 0, 0, math.floor(titleSize * 1.25)),
		ZIndex = 834, Parent = block,
	})
	List(titleRow, math.floor(titleSize * 0.08), Enum.FillDirection.Horizontal, Enum.HorizontalAlignment.Left, Enum.VerticalAlignment.Center)
	local letters = {}
	local title = string.upper(tostring(opts.Title or "NW HUB"))
	for ch in title:gmatch(utf8.charpattern) do
		local cell = New("Frame", {
			BackgroundTransparency = 1, Size = UDim2.new(0, 0, 1, 0),
			AutomaticSize = Enum.AutomaticSize.X, ZIndex = 834, Parent = titleRow,
		})
		local l = Label(cell, ch == " " and "  " or ch, titleSize, "Text", Enum.FontWeight.Bold, "Display")
		l.TextSize = titleSize
		l.AutomaticSize = Enum.AutomaticSize.X
		l.Size = UDim2.new(0, 0, 1, 0)
		l.Position = UDim2.fromScale(0, 1.1)
		l.ZIndex = 835
		table.insert(letters, l)
	end

	local subY = titleY + math.floor(titleSize * 1.3)
	local sub = Mono(block, ("KYŌKA V2   ·   %s"):format(string.upper(tostring(opts.Subtitle or "Kyōka Suigetsu"))), math.clamp(H * 0.015, 11, 16), "Glass", Enum.FontWeight.SemiBold)
	sub.Position = UDim2.fromOffset(2, subY)
	sub.Size = UDim2.new(1, 0, 0, math.floor(H * 0.03))
	sub.TextTransparency = 1
	sub.ZIndex = 835

	-- Jauge de chargement (préchargement réel des images de l'interface).
	local track = New("Frame", {
		Position = UDim2.fromOffset(2, subY + math.floor(H * 0.05)), Size = UDim2.fromOffset(math.floor(math.clamp(vp.X * 0.2, 180, 340)), 1),
		BackgroundColor3 = Color3.new(1, 1, 1), BackgroundTransparency = 1, BorderSizePixel = 0, ZIndex = 835, Parent = block,
	})
	local fill = New("Frame", { Size = UDim2.fromScale(0, 1), BorderSizePixel = 0, BackgroundTransparency = 1, ZIndex = 836, Parent = track })
	Library:Register(fill, { BackgroundColor3 = "Accent" })
	local pct = Mono(track, "", 11, "TextFaint", Enum.FontWeight.Medium)
	pct.AnchorPoint = Vector2.new(0, 0.5)
	pct.Position = UDim2.new(1, 12, 0.5, 0)
	pct.Size = UDim2.fromOffset(220, 16)
	pct.TextTransparency = 1
	pct.ZIndex = 836

	local quote = Mono(overlay, "", math.clamp(H * 0.014, 11, 15), "TextDim")
	quote.AnchorPoint = Vector2.new(0.5, 1)
	quote.Position = UDim2.new(0.5, 0, 1, -math.floor(barH * 0.38))
	quote.Size = UDim2.new(0.9, 0, 0, 20)
	quote.TextXAlignment = Enum.TextXAlignment.Center
	quote.ZIndex = 840

	local hint = Mono(overlay, "CLICK  OR  PRESS  SPACE  TO  SKIP", 10, "TextFaint", Enum.FontWeight.SemiBold)
	hint.AnchorPoint = Vector2.new(1, 0)
	hint.Position = UDim2.new(1, -margin, 0, math.floor(barH * 0.38))
	hint.Size = UDim2.fromOffset(300, 16)
	hint.TextXAlignment = Enum.TextXAlignment.Right
	hint.TextTransparency = 1
	hint.ZIndex = 840

	-- Passer : clic ou Espace / Échap / Entrée.
	local skipHit = Hit(overlay, "Skip", 850)
	local conns = {}
	ctl.Conns = conns
	table.insert(conns, skipHit.MouseButton1Click:Connect(function() skipped = true end))
	table.insert(conns, UserInputService.InputBegan:Connect(function(input)
		local k = input.KeyCode
		if k == Enum.KeyCode.Space or k == Enum.KeyCode.Escape or k == Enum.KeyCode.Return then skipped = true end
	end))

	local grainT = 0
	local live = RunService.RenderStepped:Connect(function(dt)
		grainT += dt
		if grainT > 0.05 then
			grainT = 0
			grain.Position = UDim2.fromOffset(-math.random(0, 160), -math.random(0, 160))
		end
		if stepSprite then stepSprite(dt) end
		local m = video or sprite
		if m then m.Size = cover(mediaW, mediaH, mediaZoom) end
	end)
	table.insert(conns, live)

	local function waitOr(t)
		local e = 0
		while e < t * Library.Motion and not skipped and not ctl.Done do e += task.wait() end
	end

	-- Préchargement en tâche de fond, pour la jauge.
	local loaded, total = 0, 0
	task.spawn(function()
		local list = { Assets.Icons, Assets.Icons2, Assets.Shards, Assets.Cracks, Assets.Wordmark, Assets.Fx, Assets.Grain, Assets.Shadow, Assets.Aizen }
		total = #list
		pcall(function()
			ContentProvider:PreloadAsync(list, function() loaded += 1 end)
		end)
		loaded = total
	end)
	local progressConn = RunService.Heartbeat:Connect(function()
		local p = total > 0 and loaded / total or 0
		fill.Size = UDim2.fromScale(fill.Size.X.Scale + (p - fill.Size.X.Scale) * 0.12, 1)
		pct.Text = ("%d%%   %s"):format(math.floor(fill.Size.X.Scale * 100 + 0.5), p >= 1 and "READY" or "LOADING ASSETS")
	end)
	table.insert(conns, progressConn)

	-- 1. Le filet s'allume, l'œil s'ouvre.
	Library:PlaySound("Drone")
	Tween(seam, 0.6, { Size = UDim2.fromOffset(math.floor(vp.X * 0.72), 36) }, Enum.EasingStyle.Quint)
	waitOr(0.55)
	Library:PlaySound("Boom")
	if video then pcall(function() video:Play() end) end
	if sprite then Tween(sprite, 0.6, { ImageTransparency = 0.18 }) end
	Tween(barTop, 0.9, { Size = UDim2.new(1, 0, 0, barH) }, Enum.EasingStyle.Quint)
	Tween(barBottom, 0.9, { Size = UDim2.new(1, 0, 0, barH) }, Enum.EasingStyle.Quint)
	Tween(seam, 0.5, { ImageTransparency = 1, Size = UDim2.fromOffset(vp.X, 60) })
	Tween(tint, 1.2, { BackgroundTransparency = video and 0.86 or 0.7 })
	Tween(shade, 1.2, { BackgroundTransparency = 0 })
	Tween(vig, 1.2, { ImageTransparency = 0.1 })
	Tween(grain, 1.2, { ImageTransparency = 0.88 })
	Tween(mediaScale, 6, { Scale = 1.0 }, Enum.EasingStyle.Sine)
	FX.Flash(0.12, 0.6)
	waitOr(0.6)

	-- 2. 鏡 花 水 月, un glyphe après l'autre, et la voix.
	Tween(hint, 0.6, { TextTransparency = 0.3 })
	Tween(kicker, 0.6, { TextTransparency = 0 })
	if Prefs.IntroVoice ~= false then
		task.spawn(function()
			local voice = K.Media("splash.mp3", 5000)
			if voice then Library.Sound.Splash.Id = voice end
			Library:PlaySound("Splash")
		end)
	end
	for i, g in ipairs(glyphs) do
		if skipped then break end
		Library:PlaySound(i == 1 and "Stinger" or "Tick", { Pitch = 0.7 + i * 0.08, Volume = i ~= 1 and 0.18 or nil })
		Tween(g.Img, 0.55, { ImageTransparency = 0 }, Enum.EasingStyle.Quad)
		Tween(g.Scale, 0.75, { Scale = 1 }, Enum.EasingStyle.Exponential)
		g.Glow.ImageTransparency = 0.55
		Tween(g.Glow, 0.9, { ImageTransparency = 1 }, Enum.EasingStyle.Quad)
		waitOr(0.2)
	end
	waitOr(0.25)

	-- 3. Titre lettre par lettre, sous-titre, jauge.
	for i, l in ipairs(letters) do
		Tween(l, 0.6, { Position = UDim2.fromScale(0, 0) }, Enum.EasingStyle.Exponential, nil, (i - 1) * 0.035)
	end
	Library:PlaySound("Open", { Volume = 0.25 })
	waitOr(0.25)
	Tween(sub, 0.5, { TextTransparency = 0 })
	Tween(track, 0.5, { BackgroundTransparency = 0.85 })
	Tween(fill, 0.5, { BackgroundTransparency = 0 })
	Tween(pct, 0.5, { TextTransparency = 0.2 })
	waitOr(0.4)

	-- 4. La réplique, tapée.
	local line = opts.Quote or "Since when were you under the impression this was just another script hub?"
	-- Deux caractères par image : la réplique s'écrit en ~1 s.
	local chars = {}
	for ch in line:gmatch(utf8.charpattern) do table.insert(chars, ch) end
	for i = 2, #chars, 2 do
		if skipped then break end
		quote.Text = table.concat(chars, "", 1, i) .. "▍"
		if i % 4 == 0 then Library:PlaySound("Type", { Pitch = 0.9 + math.random() * 0.3 }) end
		task.wait()
	end
	quote.Text = line
	waitOr(0.6)

	-- Script qui pilote lui-même la fin (Splash():Finish()).
	local tw = os.clock()
	while not manualDone and not skipped and os.clock() - tw < 10 do task.wait() end

	-- 5. Fissure, puis l'écran vole en éclats vers le joueur.
	finished = true
	local full = { x = 0, y = 0, w = vp.X, h = vp.Y }
	local mw = math.max(vp.X, vp.Y * 1.6) * 1.08
	local mirror = { x = (vp.X - mw) / 2, y = (vp.Y - mw / 1.6) / 2, w = mw, h = mw / 1.6 }
	Library:PlaySound("Crack", { Volume = 0.5 })
	local stopCracks = FX.Cracks(mirror, 870)
	FX.Shake(stage, 8, 0.25)
	FX.Shake(block, 6, 0.25)
	task.wait(0.32 * Library.Motion)
	Library:PlaySound("Shatter", { Volume = 0.6 })
	Library:PlaySound("Impact", { Volume = 0.35 })
	FX.Flash(0.5, 0.5)
	FX.Shockwave(Vector2.new(vp.X / 2, vp.Y / 2), vp.X * 1.2, Theme.Glass)
	stopCracks()
	FX.Shatter(mirror, nil, true, 869)
	for _, d in ipairs(overlay:GetDescendants()) do
		if d:IsA("TextLabel") then Tween(d, 0.25, { TextTransparency = 1 })
		elseif d:IsA("ImageLabel") then Tween(d, 0.25, { ImageTransparency = 1 })
		elseif d:IsA("Frame") then Tween(d, 0.3, { BackgroundTransparency = 1 }) end
	end
	if video then Tween(video, 0.25, { BackgroundTransparency = 1 }); pcall(function() video:Pause() end); video.Visible = false end
	Tween(overlay, 0.35, { BackgroundTransparency = 1 })
	local _ = full

	task.wait(0.28 * Library.Motion)
	for _, c in ipairs(conns) do pcall(function() c:Disconnect() end) end
	task.delay(0.6, function() overlay:Destroy() end)
	if ctl.Done then return finished end
	ctl.Done = true
	task.delay(1.4 * Library.Motion, function() Library.Effects = scriptFx end)
	Library.SplashActive = false
	if Library.Window and not Library.Unloaded and (Library.PendingOpen or not Library.Open) then
		Library.PendingOpen = false
		Library.Window:SetOpen(true)
	end
	return finished
end

-- L'intro ne doit jamais bloquer le menu : erreur ou durée anormale → on la retire et on ouvre.
function Library:Intro(opts)
	opts = opts or {}
	if Library.Unloaded or Library.SplashActive then return end
	Library.SplashActive = true
	Library.IntroPlayed = true
	local ctl = { Done = false, ScriptFx = Library.Effects }
	-- L'intro garde ses effets même si le script a coupé Kyoka.Effects.
	Library.Effects = true
	local function abort(reason)
		if ctl.Done then return end
		ctl.Done = true
		if reason then warn("[Kyoka] intro stopped: " .. tostring(reason)) end
		for _, c in ipairs(ctl.Conns or {}) do pcall(function() c:Disconnect() end) end
		if ctl.Overlay then pcall(function() ctl.Overlay:Destroy() end) end
		Library.Effects = ctl.ScriptFx
		Library.SplashActive = false
		if Library.Window and not Library.Unloaded then
			Library.PendingOpen = false
			pcall(function() Library.Window:SetOpen(true) end)
		end
	end
	Library._IntroAbort = abort
	task.delay(opts.Manual and 20 or 14, function()
		if not ctl.Done then abort("timeout") end
	end)
	local ok, err = pcall(RunIntro, opts, ctl)
	if not ok then abort(err) end
end

-- Compatibilité Kyōka / Vesper : écran de chargement piloté par le script.
function Library:Splash(opts)
	opts = opts or {}
	local handle = { Progress = 0 }
	if not Library.IntroPlayed and Library.Intro then
		task.spawn(function()
			Library:Intro({ Title = opts.Title, Subtitle = opts.Subtitle, Manual = opts.AutoFinish == false })
		end)
	end
	function handle:SetProgress(v) handle.Progress = math.clamp(tonumber(v) or 0, 0, 1) end
	function handle:Finish()
		handle.Done = true
		if Library._IntroRelease then Library._IntroRelease() end
	end
	Library.CurrentSplash = handle
	return handle
end

