local NOTIF_KIND = {
	info = { "Accent", "info" }, success = { "Success", "success" },
	error = { "Danger", "error" }, warning = { "Warning", "alert" },
}

function Library:Notify(opts, duration)
	if type(opts) == "string" then opts = { Content = opts, Duration = duration } end
	opts = opts or {}
	local dur = tonumber(opts.Duration or opts.Time) or 4
	local kind = NOTIF_KIND[string.lower(tostring(opts.Type or "info"))] or NOTIF_KIND.info
	local color = opts.Color or Theme[kind[1]]

	local slot = New("Frame", {
		Name = "Slot", BackgroundTransparency = 1,
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y,
		ZIndex = 700, Parent = NotifHolder,
	})
	local spacing = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 8), LayoutOrder = 2, Parent = slot })
	List(slot, 0)
	local wrap = New("Frame", {
		Name = "Wrap", BackgroundTransparency = 1, LayoutOrder = 1,
		Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 701, Parent = slot,
	})
	local _ = spacing
	local card = New("CanvasGroup", {
		Name = "Notification",
		Size = UDim2.new(1, 0, 0, 0),
		AutomaticSize = Enum.AutomaticSize.Y,
		Position = UDim2.fromOffset(40, 0),
		GroupTransparency = 1,
		ZIndex = 702,
		Parent = wrap,
	})
	Library:Register(card, { BackgroundColor3 = "Panel2" })
	Corner(card, 10)
	local edge = New("Frame", { BackgroundTransparency = 1, Size = UDim2.fromScale(1, 1), Position = UDim2.fromOffset(40, 0), ZIndex = 710, Parent = wrap })
	Corner(edge, 10)
	local edgeStroke = Stroke(edge, "Border", 1, 1)

	local tile = New("Frame", { Position = UDim2.fromOffset(12, 12), Size = UDim2.fromOffset(30, 30), BackgroundColor3 = color, BackgroundTransparency = 0.84, ZIndex = 703, Parent = card })
	Corner(tile, 8)
	local ic = Icon(tile, kind[2], 16, nil, 704)
	ic.ImageColor3 = color
	ic.AnchorPoint = Vector2.new(0.5, 0.5)
	ic.Position = UDim2.fromScale(0.5, 0.5)

	local body = New("Frame", {
		BackgroundTransparency = 1, Position = UDim2.fromOffset(54, 0),
		Size = UDim2.new(1, -66, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 703, Parent = card,
	})
	Pad(body, 12, 15, 0, 0)
	List(body, 2)
	if opts.Title then
		local t = Label(body, opts.Title, 13, "Text", Enum.FontWeight.SemiBold)
		t.Size = UDim2.new(1, 0, 0, 17)
		t.TextTruncate = Enum.TextTruncate.AtEnd
		t.LayoutOrder = 1
		t.ZIndex = 704
	end
	local c = Label(body, opts.Content or opts.Description or opts.Text or "", 12.5, "TextDim")
	c.TextWrapped = true
	c.AutomaticSize = Enum.AutomaticSize.Y
	c.Size = UDim2.new(1, 0, 0, 0)
	c.TextYAlignment = Enum.TextYAlignment.Top
	c.LayoutOrder = 2
	c.ZIndex = 704

	local bar = New("Frame", {
		AnchorPoint = Vector2.new(0, 1), Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 0, 2), BorderSizePixel = 0, BackgroundColor3 = color,
		BackgroundTransparency = 0.2, ZIndex = 705, Parent = card,
	})

	local closed, remaining, paused = false, dur, false
	local function close()
		if closed then return end
		closed = true
		Tween(card, 0.25, { GroupTransparency = 1, Position = UDim2.fromOffset(40, 0) }, Enum.EasingStyle.Quad)
		Tween(edgeStroke, 0.2, { Transparency = 1 })
		task.delay(0.24 * Library.Motion, function()
			local h = slot.AbsoluteSize.Y / math.max(Factor(), 0.01)
			slot.AutomaticSize = Enum.AutomaticSize.None
			slot.Size = UDim2.new(1, 0, 0, h)
			slot.ClipsDescendants = true
			Tween(slot, 0.22, { Size = UDim2.new(1, 0, 0, 0) }, Enum.EasingStyle.Quad)
			task.delay(0.24 * Library.Motion, function() slot:Destroy() end)
		end)
	end

	local hit = Hit(card, "NotifHit", 720)
	Library:Connect(hit.MouseButton1Click, close)
	Library:Connect(hit.MouseEnter, function() paused = true end)
	Library:Connect(hit.MouseLeave, function() paused = false end)

	Tween(card, 0.45, { GroupTransparency = 0, Position = UDim2.fromOffset(0, 0) }, Enum.EasingStyle.Quint)
	Tween(edge, 0.45, { Position = UDim2.fromOffset(0, 0) }, Enum.EasingStyle.Quint)
	Tween(edgeStroke, 0.3, { Transparency = 0 })
	Library:PlaySound(kind[1] == "Danger" and "Error" or "Notify")
	task.delay(0.1, function() if not closed then FX.Sweep(card, 0, 0.7, 0.9) end end)

	local conn
	conn = RunService.Heartbeat:Connect(function(dt)
		if closed then conn:Disconnect() return end
		if not paused then remaining -= dt end
		bar.Size = UDim2.new(math.clamp(remaining / dur, 0, 1), 0, 0, 2)
		if remaining <= 0 then conn:Disconnect(); close() end
	end)
	table.insert(Library.Connections, conn)

	local handle = { Instance = card }
	function handle:Close() close() end
	function handle:SetContent(t) c.Text = tostring(t) end
	return handle
end

