local watermarkTemplate, watermarkWanted = "", false
local function ApplyWatermark()
	local want = watermarkWanted
	if Prefs.Watermark ~= nil then want = Prefs.Watermark and watermarkTemplate ~= "" end
	Watermark.Visible = want and watermarkTemplate ~= ""
end
K.ApplyWatermark = ApplyWatermark

function Library:SetWatermark(text, visible)
	watermarkTemplate = text or ""
	watermarkWanted = visible ~= false
	ApplyWatermark()
end
function Library:SetWatermarkVisible(v)
	watermarkWanted = v and true or false
	ApplyWatermark()
end
function Library:SetWatermarkPosition(position, anchor)
	Watermark.AnchorPoint = anchor or Vector2.new(0.5, 0)
	Watermark.Position = position or UDim2.new(0.5, 0, 0, 10)
end

do
	local frames, acc, fps = 0, 0, 60
	Library:Connect(RunService.RenderStepped, function(dt)
		frames += 1
		acc += dt
		if acc < 0.5 then return end
		fps = math.floor(frames / acc + 0.5)
		frames, acc = 0, 0
		if not Watermark.Visible then return end
		local ping = 0
		pcall(function() ping = math.floor(Stats.Network.ServerStatsItem["Data Ping"]:GetValue()) end)
		local out = watermarkTemplate
			:gsub("{[Ff][Pp][Ss]}", tostring(fps))
			:gsub("{[Pp][Ii][Nn][Gg]}", tostring(ping) .. "ms")
			-- Le pseudo n'est jamais affiché (captures, streams) : {player} est retiré.
			:gsub("{[Pp][Ll][Aa][Yy][Ee][Rr]}%s*[/|]%s*", "")
			:gsub("[/|]%s*{[Pp][Ll][Aa][Yy][Ee][Rr]}", "")
			:gsub("{[Pp][Ll][Aa][Yy][Ee][Rr]}", "")
			:gsub("{[Tt][Ii][Mm][Ee]}", os.date("%H:%M:%S"))
			:gsub("{[Gg][Aa][Mm][Ee]}", tostring(Library.WindowOptions and Library.WindowOptions.Game or ""))
		local parts = {}
		for seg in out:gmatch("[^/|]+") do
			local s = seg:match("^%s*(.-)%s*$")
			if s ~= "" then table.insert(parts, s) end
		end
		local head = table.remove(parts, 1) or ""
		WatermarkText.Text = ('<font color="#%s"><b>%s</b></font>'):format(Theme.Text:ToHex(), string.upper(head))
			.. (#parts > 0 and ("   " .. string.upper(table.concat(parts, "  ·  "))) or "")
	end)
end

