local QuickRows = {}

local function Pins()
	Prefs.Pins = type(Prefs.Pins) == "table" and Prefs.Pins or {}
	local gk = K.GameKey()
	Prefs.Pins[gk] = type(Prefs.Pins[gk]) == "table" and Prefs.Pins[gk] or {}
	return Prefs.Pins[gk]
end
K.Pins = Pins

local function RefreshQuick()
	for _, r in pairs(QuickRows) do r.Frame:Destroy() end
	table.clear(QuickRows)
	local list = Pins()
	local n = 0
	for i, flag in ipairs(list) do
		local obj = Library.Options[flag]
		if obj and (obj.Type == "Toggle" or obj.Type == "Button" or obj.Type == "Slider") then
			n += 1
			local frame = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 28), LayoutOrder = i, ZIndex = 612, Parent = QuickBody })
			local name = Label(frame, obj.Text or flag, 12.5, "TextDim")
			name.Size = UDim2.new(1, -60, 1, 0)
			name.TextTruncate = Enum.TextTruncate.AtEnd
			name.ZIndex = 613
			local right = New("Frame", { BackgroundTransparency = 1, AnchorPoint = Vector2.new(1, 0.5), Position = UDim2.new(1, 0, 0.5, 0), Size = UDim2.fromOffset(56, 24), ZIndex = 613, Parent = frame })
			local row = { Frame = frame }
			if obj.Type == "Toggle" then
				local track, set = K.Switch(right, 30, 17)
				track.AnchorPoint = Vector2.new(1, 0.5)
				track.Position = UDim2.new(1, 0, 0.5, 0)
				set(obj.Value, true)
				local h = Hit(frame, "QuickHit", 620)
				Library:Connect(h.MouseButton1Click, function() obj:Set(not obj.Value) end)
				row.Sync = function()
					if row.Last ~= obj.Value then
						row.Last = obj.Value
						set(obj.Value)
						Paint(name, 0, "TextColor3", obj.Value and "Text" or "TextDim")
					end
				end
			elseif obj.Type == "Slider" then
				local v = Mono(right, "", 11, "Text", Enum.FontWeight.SemiBold)
				v.TextXAlignment = Enum.TextXAlignment.Right
				v.ZIndex = 614
				row.Sync = function() v.Text = tostring(K.Round(obj.Value, obj.Rounding or 0)) .. (obj.Suffix or "") end
			else
				local ic = Icon(right, "play", 13, "Accent", 614)
				ic.AnchorPoint = Vector2.new(1, 0.5)
				ic.Position = UDim2.new(1, -4, 0.5, 0)
				local h = Hit(frame, "QuickHit", 620)
				Library:Connect(h.MouseButton1Click, function()
					Library:PlaySound("Click")
					FX.Pulse(ic)
					if obj.Callback then task.spawn(obj.Callback) end
				end)
			end
			QuickRows[flag] = row
		end
	end
	QuickCount.Text = tostring(n)
	Quick.Visible = n > 0 and Prefs.QuickBar ~= false
end
K.RefreshQuick = RefreshQuick

Library:Connect(RunService.Heartbeat, function()
	if not Quick.Visible then return end
	for _, r in pairs(QuickRows) do if r.Sync then r.Sync() end end
end)

function Library:PinToQuickBar(flag)
	local list = Pins()
	if not table.find(list, flag) then table.insert(list, flag) end
	K.SavePrefs()
	RefreshQuick()
end
function Library:UnpinFromQuickBar(flag)
	local list = Pins()
	local i = table.find(list, flag)
	if i then table.remove(list, i) end
	K.SavePrefs()
	RefreshQuick()
end
-- Les options n'existent qu'une fois le script construit.
task.delay(1.5, RefreshQuick)

