-- Contrôle vivant à droite d'un résultat.
local function LiveControl(e)
	return function(holder)
		local obj = e.Obj
		if e.Kind == "toggle" and type(obj) == "table" then
			local track, set = K.Switch(holder, 30, 17)
			track.AnchorPoint = Vector2.new(1, 0.5)
			track.Position = UDim2.new(1, 0, 0.5, 0)
			set(obj.Value, true)
			e._sync = function() set(obj.Value) end
		elseif e.Kind == "slider" and type(obj) == "table" then
			local v = Mono(holder, "", 11.5, "Text", Enum.FontWeight.SemiBold)
			v.TextXAlignment = Enum.TextXAlignment.Right
			v.ZIndex = 774
			local function sync() v.Text = ("‹ %s%s ›"):format(tostring(K.Round(obj.Value, obj.Rounding or 0)), obj.Suffix or "") end
			sync()
			e._sync = sync
		elseif e.Kind == "dropdown" and type(obj) == "table" then
			local v = Mono(holder, "", 10.5, "TextDim")
			v.TextXAlignment = Enum.TextXAlignment.Right
			v.TextTruncate = Enum.TextTruncate.AtEnd
			v.ZIndex = 774
			local val = obj.Value
			v.Text = type(val) == "table" and (#val .. " selected") or tostring(val or "—")
		elseif e.Kind == "keybind" and type(obj) == "table" and obj.Value then
			local v = Mono(holder, string.upper(KeyName(obj.Value.Key)), 10.5, "TextDim", Enum.FontWeight.SemiBold)
			v.TextXAlignment = Enum.TextXAlignment.Right
			v.ZIndex = 774
		end
	end
end

local function Reveal(e)
	if not e or not e.Group then return end
	local page = e.Group.Page
	local tab = page and page.Tab
	A.Close()
	if Library.Window and not Library.Open then Library.Window:SetOpen(true) end
	if tab then tab:Select(true) end
	if page and page.Select then page.Select(true) end
	task.delay(0.15, function()
		local row = e.Row
		if not row or not row.Parent then return end
		local col = row:FindFirstAncestorOfClass("ScrollingFrame")
		if col then
			local top = row.AbsolutePosition.Y - col.AbsolutePosition.Y + col.CanvasPosition.Y
			col.CanvasPosition = Vector2.new(0, math.max(top - col.AbsoluteSize.Y * 0.35, 0))
		end
		local hover = row:FindFirstChild("Hover")
		if hover then
			hover.BackgroundColor3 = Theme.Accent
			hover.BackgroundTransparency = 0.7
			Tween(hover, 1.1, { BackgroundTransparency = 1 }, Enum.EasingStyle.Quad)
			task.delay(1.15, function() hover.BackgroundColor3 = Theme.ElementHover end)
		end
	end)
end
A.Reveal = Reveal

local function Remember(e)
	for i = #A.Recent, 1, -1 do if A.Recent[i] == e then table.remove(A.Recent, i) end end
	table.insert(A.Recent, 1, e)
	while #A.Recent > 5 do table.remove(A.Recent) end
end

local function RunEntry(e, row)
	Remember(e)
	local obj = e.Obj
	if e.Kind == "command" then
		A.Close()
		task.spawn(e.Run)
	elseif e.Kind == "toggle" then
		obj:Set(not obj.Value)
		if e._sync then e._sync() end
		if row then FX.Pulse(row.Frame, Theme.Accent, 1.4) end
	elseif e.Kind == "button" then
		Library:PlaySound("Click")
		if obj.Callback then task.spawn(obj.Callback) end
		if row then FX.Pulse(row.Frame, Theme.Accent, 1.4) end
	else
		Reveal(e)
	end
end

local function Step(e, dir)
	if e.Kind ~= "slider" then return end
	local obj = e.Obj
	local stepSize = (10 ^ -(obj.Rounding or 0))
	local range = (obj.Max or 100) - (obj.Min or 0)
	if range / stepSize > 60 then stepSize = range / 40 end
	obj:Set((obj.Value or 0) + stepSize * dir)
	if e._sync then e._sync() end
end

--=====================================================================
-- Rendu
--=====================================================================

local Reply

local function Render()
	ClearRows()
	A.Actions = {}
	local q = Input.Text or ""
	local order = 0
	local function nextOrder() order += 1 return order end

	if q:match("^%s*$") then
		if A.LastReply and os.clock() - A.LastReply.At < 5 then
			local c = Caption(A.LastReply.Text, nextOrder())
			Unregister(c, "TextColor3")
			c.TextColor3 = Theme.Success
		end
		local pinned = {}
		for _, flag in ipairs(A.Pinned) do
			for _, e in ipairs(A.Entries) do if e.Flag == flag then table.insert(pinned, e) break end end
		end
		if #A.Recent > 0 then
			Caption("Recent", nextOrder())
			for _, e in ipairs(A.Recent) do ResultRow(nextOrder(), KIND_ICON[e.Kind] or "star", e.Text, PathOf(e), LiveControl(e), { Entry = e }) end
		end
		if #pinned > 0 then
			Caption("Pinned", nextOrder())
			for _, e in ipairs(pinned) do ResultRow(nextOrder(), KIND_ICON[e.Kind] or "star", e.Text, PathOf(e), LiveControl(e), { Entry = e }) end
		end
		Caption("Try asking", nextOrder())
		for _, ex in ipairs(EXAMPLES) do
			ResultRow(nextOrder(), "sparkles", ex, nil, nil, { Example = ex })
		end
		SelectRow(1)
		return
	end

	-- 1. Ce que Kyōka propose de faire.
	local actions = Parse(q)
	local runnable = {}
	for _, a in ipairs(actions) do if a.Run then table.insert(runnable, a) end end
	if #runnable > 0 then
		Caption(#runnable > 1 and ("Kyōka will do " .. #runnable .. " things") or "Kyōka will", nextOrder())
		ResultRow(nextOrder(), "wand", #runnable > 1 and ("Run all " .. #runnable .. " actions") or runnable[1].Label,
			(#runnable == 1 and runnable[1].Entry) and PathOf(runnable[1].Entry) or nil, function(holder)
				local k = Mono(holder, "ENTER", 10, "Accent", Enum.FontWeight.Bold)
				k.TextXAlignment = Enum.TextXAlignment.Right
				k.ZIndex = 774
			end, { Actions = runnable, Danger = runnable[1].Danger and #runnable == 1 })
		if #runnable > 1 then
			for _, a in ipairs(runnable) do
				ResultRow(nextOrder(), a.Icon or "check", a.Label, a.Entry and PathOf(a.Entry) or nil, nil, { Actions = { a }, Danger = a.Danger })
			end
		end
	end

	-- 2. Résultats de recherche (options + commandes).
	local words = Tokens(q)
	local scored = {}
	for _, e in ipairs(A.Entries) do
		if e.Row and e.Row.Parent then
			local s = Score(words, e.Text, PathOf(e))
			if s >= 0.45 then table.insert(scored, { e, s }) end
		end
	end
	for _, c in ipairs(A.Commands) do
		local s = Score(words, c.Text .. " " .. table.concat(c.Keywords or {}, " "))
		if s >= 0.45 then table.insert(scored, { c, s + 0.05 }) end
	end
	table.sort(scored, function(a, b) return a[2] > b[2] end)
	if #scored > 0 then
		Caption("Options", nextOrder())
		for i = 1, math.min(#scored, 12) do
			local e = scored[i][1]
			ResultRow(nextOrder(), KIND_ICON[e.Kind] or "star", e.Text, e.Kind == "command" and "COMMAND" or PathOf(e), LiveControl(e), { Entry = e, Danger = e.Danger })
		end
	end

	if #runnable == 0 and #scored == 0 then
		Caption("No match", nextOrder())
		local hint = Library.AI.Endpoint and "Press Enter to ask the AI model" or "Try an option name, or \"enable …\", \"set … to 10\""
		ResultRow(nextOrder(), "sparkles", hint, nil, nil, { Remote = Library.AI.Endpoint ~= nil })
	end
	SelectRow(1)
end

-- Modèle distant (optionnel) : POST { prompt, options } → { reply, actions = { { flag, value } } }.
local function AskRemote(prompt)
	local req = (syn and syn.request) or (http and http.request) or http_request or request
	if not (Library.AI.Endpoint and req) then return end
	local options = {}
	for _, e in ipairs(A.Entries) do
		if e.Flag and e.Obj then
			table.insert(options, { flag = e.Flag, text = e.Text, kind = e.Kind, path = PathOf(e),
				min = e.Obj.Min, max = e.Obj.Max, values = e.Obj.Values })
		end
	end
	FootRight.Text = "THINKING…"
	local ok, res = pcall(req, {
		Url = Library.AI.Endpoint, Method = "POST",
		Headers = (function() local h = { ["Content-Type"] = "application/json" } for k, v in pairs(Library.AI.Headers or {}) do h[k] = v end return h end)(),
		Body = HttpService:JSONEncode({ prompt = prompt, options = options, game = Library.WindowOptions and Library.WindowOptions.Game }),
	})
	FootRight.Text = "KYŌKA ASSIST"
	if not ok or not res or not res.Body then
		Library:Notify({ Title = "Kyōka Assist", Content = "The AI model did not answer.", Type = "error" })
		return
	end
	local okd, data = pcall(function() return HttpService:JSONDecode(res.Body) end)
	if not okd or type(data) ~= "table" then return end
	local n = 0
	for _, a in ipairs(data.actions or {}) do
		local obj = Library.Options[a.flag]
		if obj and obj.Set then pcall(obj.Set, obj, a.value); n += 1 end
	end
	if data.reply then Library:Notify({ Title = "Kyōka", Content = tostring(data.reply), Duration = 6 }) end
	if n > 0 then FX.Burst(Spark.AbsolutePosition + Spark.AbsoluteSize / 2, 10) end
end

A.Run = function(row)
	local d = row and row.Data
	if not d then return end
	if d.Example then
		Input.Text = d.Example
		Input:CaptureFocus()
		return
	end
	if d.Remote then
		local q = Input.Text
		A.Close()
		task.spawn(AskRemote, q)
		return
	end
	if d.Actions then
		local n, revealTarget = 0, nil
		for _, a in ipairs(d.Actions) do
			if a.Run then
				local ok = pcall(a.Run)
				if ok then n += 1 end
				if a.Entry then Remember(a.Entry); revealTarget = revealTarget or a.Entry end
			end
		end
		FX.Burst(Spark.AbsolutePosition + Spark.AbsoluteSize / 2, 12)
		Library:PlaySound("ToggleOn", { Pitch = 1.2 })
		if Reply then Reply(n) end
		return
	end
	if d.Entry then RunEntry(d.Entry, row) end
end

Reply = function(n)
	A.LastReply = { Text = ("Done  ·  %d change%s applied"):format(n, n == 1 and "" or "s"), At = os.clock() }
	Input.Text = ""
	Render()
end

--=====================================================================
-- Ouverture / fermeture
--=====================================================================

local exampleIdx = 0
local function Open()
	if A.Shown or not Library.PaletteEnabled or Library.Unloaded then return end
	A.Shown = true
	A.OpenedAt = os.clock()
	K.CloseActivePopup()
	exampleIdx = exampleIdx % #EXAMPLES + 1
	Input.PlaceholderText = "Ask Kyōka…  e.g. \"" .. EXAMPLES[exampleIdx] .. "\""
	Input.Text = ""
	HolderScale.Scale = Factor()
	Holder.Visible = true
	Dim.Visible = true
	Card.GroupTransparency = 1
	Card.Position = UDim2.fromOffset(0, -10)
	Edge.Position = UDim2.fromOffset(0, -10)
	EdgeStroke.Transparency = 1
	Tween(Dim, 0.2, { BackgroundTransparency = 0.5 })
	Tween(Card, 0.3, { GroupTransparency = 0, Position = UDim2.new() }, Enum.EasingStyle.Quint)
	Tween(Edge, 0.3, { Position = UDim2.new() }, Enum.EasingStyle.Quint)
	Tween(EdgeStroke, 0.3, { Transparency = 0 })
	Spark.Rotation = -40
	Tween(Spark, 0.6, { Rotation = 0 }, Enum.EasingStyle.Back)
	Library:PlaySound("Open", { Volume = 0.2, Pitch = 1.3 })
	K.Modal.Modal = true
	Library:ShowCursor(true)
	Render()
	task.defer(function() Input:CaptureFocus() end)
end

local function Close()
	if not A.Shown then return end
	A.Shown = false
	Tween(Dim, 0.15, { BackgroundTransparency = 1 })
	Tween(Card, 0.15, { GroupTransparency = 1, Position = UDim2.fromOffset(0, -6) }, Enum.EasingStyle.Quad)
	Tween(Edge, 0.15, { Position = UDim2.fromOffset(0, -6) }, Enum.EasingStyle.Quad)
	Tween(EdgeStroke, 0.12, { Transparency = 1 })
	Input:ReleaseFocus()
	task.delay(0.16 * Library.Motion, function()
		if not A.Shown then Holder.Visible = false; Dim.Visible = false end
	end)
	if not Library.Open then
		K.Modal.Modal = false
		Library:ShowCursor(false)
	end
end
A.Close = Close

-- Le clic qui ouvre l'assistant ne doit pas le refermer en retombant sur le fond.
Library:Connect(Dim.MouseButton1Click, function()
	if os.clock() - (A.OpenedAt or 0) > 0.3 then Close() end
end)
Library:Connect(Input:GetPropertyChangedSignal("Text"), function()
	if not A.Shown then return end
	Render()
	Scan.Position = UDim2.new(0, -100, 1, 0)
	Scan.ImageTransparency = 0.3
	Tween(Scan, 0.6, { Position = UDim2.new(1, 100, 1, 0), ImageTransparency = 0.8 }, Enum.EasingStyle.Quad)
end)
Library:Connect(Input.FocusLost, function(enter)
	if enter and A.Shown then
		if A.Selected then A.Run(A.Selected) end
		task.defer(function() if A.Shown then Input:CaptureFocus() end end)
	end
end)

Library:Connect(UserInputService.InputBegan, function(input)
	local k = input.KeyCode
	local ctrl = UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) or UserInputService:IsKeyDown(Enum.KeyCode.RightControl)
	if k == Library.PaletteKey and ctrl then
		if A.Shown then Close() else Open() end
		return
	end
	if not A.Shown then return end
	if k == Enum.KeyCode.Escape then Close()
	elseif k == Enum.KeyCode.Down then SelectRow(A.Index + 1)
	elseif k == Enum.KeyCode.Up then SelectRow(A.Index - 1)
	elseif k == Enum.KeyCode.Tab then
		local d = A.Selected and A.Selected.Data
		if d and d.Entry and d.Entry.Kind ~= "command" then Reveal(d.Entry) end
	elseif k == Enum.KeyCode.Right or k == Enum.KeyCode.Left then
		local d = A.Selected and A.Selected.Data
		if d and d.Entry and d.Entry.Kind == "slider" then Step(d.Entry, k == Enum.KeyCode.Right and 1 or -1) end
	end
end)

function Library:OpenPalette() Open() end
function Library:ClosePalette() Close() end
function Library:TogglePalette() if A.Shown then Close() else Open() end end
function Library:SetPaletteEnabled(v) Library.PaletteEnabled = v and true or false; if not v then Close() end end
function Library:AddCommand(name, opts)
	opts = opts or {}
	local cmd = { Kind = "command", Text = tostring(name), Keywords = opts.Keywords, Danger = opts.Danger, Run = opts.Callback or opts.Run or function() end }
	table.insert(A.Commands, cmd)
	return cmd
end
function Library:PinFlag(flag)
	if not table.find(A.Pinned, flag) then table.insert(A.Pinned, flag) end
end
function Library:UnpinFlag(flag)
	local i = table.find(A.Pinned, flag)
	if i then table.remove(A.Pinned, i) end
end
function Library:SetAI(cfg)
	if type(cfg) == "string" then cfg = { Endpoint = cfg } end
	Library.AI.Endpoint = cfg and cfg.Endpoint
	Library.AI.Headers = cfg and cfg.Headers or {}
end
-- Exécuter une phrase depuis le script (ex. raccourci personnalisé).
function Library:Ask(text)
	local n = 0
	for _, a in ipairs(Parse(text)) do if a.Run and pcall(a.Run) then n += 1 end end
	return n
end

-- Commandes intégrées.
Library:AddCommand("Customize the interface", { Keywords = { "theme", "settings", "personnaliser", "apparence" }, Callback = function()
	if Library.Window and Library.Window.ToggleCustomize then
		if not Library.Open then Library.Window:SetOpen(true) end
		Library.Window:ToggleCustomize(true)
	end
end })
Library:AddCommand("Replay the intro", { Keywords = { "cinematic", "aizen", "splash" }, Callback = function()
	if Library.Window then Library.Window:SetOpen(false, true) end
	Library.IntroPlayed = false
	Library:Intro({ Title = Library.WindowOptions and Library.WindowOptions.Title, Subtitle = Library.WindowOptions and (Library.WindowOptions.Game or Library.WindowOptions.Subtitle) })
end })
Library:AddCommand("Reset window position", { Keywords = { "layout", "center", "recentrer" }, Callback = function()
	if Library.Window then Library.Window:ResetLayout() end
end })
Library:AddCommand("Toggle sidebar", { Keywords = { "compact", "collapse" }, Callback = function()
	if Library.Window then Library.Window:SetCompact(not Prefs.Compact) end
end })

