-- Menu contextuel (clic droit sur une option)
--=====================================================================

local Ctx = New("Frame", {
	Name = "Context", Size = UDim2.fromOffset(200, 0), AutomaticSize = Enum.AutomaticSize.Y,
	Visible = false, ZIndex = 750, Parent = ScreenGui,
})
Library:Register(Ctx, { BackgroundColor3 = "Panel2" })
Corner(Ctx, 9)
Stroke(Ctx, "Border")
local CtxScale = Scalable(Ctx)
local CtxInner = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 0), AutomaticSize = Enum.AutomaticSize.Y, ZIndex = 751, Parent = Ctx })
Pad(CtxInner, 5, 5, 5, 5)
List(CtxInner, 1)
local ctxItems = {}

local function CloseCtx() Ctx.Visible = false end

local function CtxItem(icon, text, danger, fn)
	local it = New("Frame", { BackgroundTransparency = 1, Size = UDim2.new(1, 0, 0, 30), LayoutOrder = #ctxItems + 1, ZIndex = 752, Parent = CtxInner })
	Library:Register(it, { BackgroundColor3 = "Element" })
	Corner(it, 6)
	local ic = Icon(it, icon, 14, danger and "Danger" or "TextDim", 753)
	ic.AnchorPoint = Vector2.new(0, 0.5)
	ic.Position = UDim2.new(0, 9, 0.5, 0)
	local t = Label(it, text, 12.5, danger and "Danger" or "Text")
	t.Position = UDim2.fromOffset(32, 0)
	t.Size = UDim2.new(1, -40, 1, 0)
	t.ZIndex = 753
	local h = Hit(it, "CtxHit", 754)
	Library:Connect(h.MouseEnter, function() Tween(it, 0.08, { BackgroundTransparency = 0 }) end)
	Library:Connect(h.MouseLeave, function() Tween(it, 0.1, { BackgroundTransparency = 1 }) end)
	Library:Connect(h.MouseButton1Click, function()
		CloseCtx()
		Library:PlaySound("Click")
		task.spawn(fn)
	end)
	table.insert(ctxItems, it)
end

K.OpenContext = function(obj)
	if type(obj) ~= "table" then return end
	for _, it in ipairs(ctxItems) do it:Destroy() end
	table.clear(ctxItems)
	local flag = obj.Flag
	if flag and (obj.Type == "Toggle" or obj.Type == "Slider") then
		local pinned = table.find(K.Pins(), flag) ~= nil
		CtxItem("pin", pinned and "Unpin from Quick bar" or "Pin to Quick bar", false, function()
			if pinned then Library:UnpinFromQuickBar(flag) else
				Library:PinToQuickBar(flag)
				Library:Notify({ Title = "Quick bar", Content = (obj.Text or flag) .. " pinned. It stays on screen even with the menu closed.", Duration = 3 })
			end
		end)
	elseif obj.Type == "Button" and obj.Entry then
		-- Les boutons n'ont pas de flag : on en crée un pour la barre rapide.
		local key = "__btn_" .. tostring(obj.Text)
		Library.Options[key] = Library.Options[key] or obj
		obj.Flag = obj.Flag or nil
		CtxItem("pin", "Pin to Quick bar", false, function() Library:PinToQuickBar(key) end)
	end
	if flag then
		local pinnedA = table.find(A.Pinned, flag) ~= nil
		CtxItem("star", pinnedA and "Remove from favorites" or "Add to favorites", false, function()
			if pinnedA then Library:UnpinFlag(flag) else Library:PinFlag(flag) end
		end)
	end
	if obj.Default ~= nil and obj.Set and obj.Type ~= "Button" then
		CtxItem("refresh", "Reset to default", false, function() obj:Set(obj.Default) end)
	end
	if flag and type(setclipboard) == "function" then
		CtxItem("copy", "Copy flag name", false, function() setclipboard(flag) end)
	end
	CtxItem("sparkles", "Ask Kyōka about it", false, function()
		Open()
		Input.Text = tostring(obj.Text or "")
	end)
	local x, y = MouseLocal()
	local vp = ViewportSize()
	CtxScale.Scale = Factor()
	Ctx.Position = UDim2.fromOffset(math.min(x + 4, vp.X - 210 * Factor()), math.min(y + 4, vp.Y - (#ctxItems * 31 + 12) * Factor()))
	Ctx.Visible = true
	Library:PlaySound("Popup")
end

Library:Connect(UserInputService.InputBegan, function(input)
	if not Ctx.Visible then return end
	if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.MouseButton2 or input.UserInputType == Enum.UserInputType.Touch then
		task.defer(function()
			if not K.PointInside(Ctx, MousePos()) then CloseCtx() end
		end)
	elseif input.KeyCode == Enum.KeyCode.Escape then
		CloseCtx()
	end
end)

end)()

