local function safeMoveTo(targetPos, speed)
    local char = LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")
    if not hrp or not hum or hum.Health <= 0 then return end

    local targetV3 = typeof(targetPos) == "CFrame" and targetPos.Position or targetPos
    local totalDist = (hrp.Position - targetV3).Magnitude
    if totalDist <= 6.0 then return end

    isTravelling = true
    pcall(function() char:SetAttribute("DisableFallDamage", true) end)

    local targetSpeed = math.clamp(speed or Hub.Flags.TravelGlideSpeed or 55, 30, 65)
    local origSpeed = hum.WalkSpeed
    hum.WalkSpeed = targetSpeed

    -- Intelligent Pathfinding around obstacles, buildings, fences and terrain
    local waypoints = nil
    pcall(function()
        cloverPathfinder:ComputeAsync(hrp.Position, targetV3)
        if cloverPathfinder.Status == Enum.PathStatus.Success then
            waypoints = cloverPathfinder:GetWaypoints()
        end
    end)

    if waypoints and #waypoints > 1 then
        for i = 2, #waypoints do
            if not Hub.Alive or not hum or hum.Health <= 0 or not isTravelling then break end
            local wp = waypoints[i]
            hum:MoveTo(wp.Position)
            if wp.Action == Enum.PathWaypointAction.Jump then
                hum:ChangeState(Enum.HumanoidStateType.Jumping)
            end
            local t0 = os.clock()
            while (hrp.Position - wp.Position).Magnitude > 4.5 and (os.clock() - t0) < 1.2 do
                task.wait()
            end
            if (hrp.Position - targetV3).Magnitude <= 7.0 then
                break
            end
        end
    else
        -- Direct physical MoveTo with timeout
        hum:MoveTo(targetV3)
        local t0 = os.clock()
        while (hrp.Position - targetV3).Magnitude > 6.0 and (os.clock() - t0) < 3.0 do
            task.wait()
        end
    end

    if hum and hum.Health > 0 then
        hum.WalkSpeed = (origSpeed and origSpeed > 0) and origSpeed or 16
    end
    isTravelling = false
end

-- Safe Weapon Detection & Equip
local function getBaseToolName(name)
    if not name then return "" end
    return (name:gsub("_%x%x%x%x%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%-%x%x%x%x%x%x%x%x%x%x%x%x$", ""))
end

local NON_COMBAT_TOOLS = {
    ["initiates broom"] = true,
    ["broom"] = true,
    ["quest index"] = true,
    ["stone pickaxe"] = true,
    ["pickaxe"] = true,
    ["stone sickle"] = true,
    ["sickle"] = true,
    ["fishing rod"] = true,
}

local function isCombatTool(tool)
    if not tool or not tool:IsA("Tool") then return false end
    local base = getBaseToolName(tool.Name):lower()
    if NON_COMBAT_TOOLS[base] or NON_COMBAT_TOOLS[tool.Name:lower()] then return false end
    if tool:GetAttribute("Sword") or tool:GetAttribute("Combat") or tool:GetAttribute("Dagger") 
       or tool:GetAttribute("Weapon") or tool:GetAttribute("Greatsword") or tool:GetAttribute("Spear") then
        return true
    end
    if base:find("blade") or base:find("sword") or base:find("katana") or base:find("fist") 
       or base:find("dagger") or base:find("spear") or base:find("scythe") or base:find("axe") 
       or base:find("hammer") or base:find("rapier") or base:find("mace") then
        return true
    end
    return false
end

local function getAvailableCombatWeapons()
    local weapons = { "Auto / Best" }
    local seen = { ["Auto / Best"] = true }
    local function scan(c)
        if not c then return end
        for _, t in ipairs(c:GetChildren()) do
            if isCombatTool(t) then
                local base = getBaseToolName(t.Name)
                if not seen[base] then
                    seen[base] = true
                    table.insert(weapons, base)
                end
            end
        end
    end
    scan(LocalPlayer.Character)
    scan(LocalPlayer:FindFirstChild("Backpack"))
    return weapons
end

local function equipWeapon(targetName)
    local char = LocalPlayer.Character
    if not char then return end
    local hum = char:FindFirstChildOfClass("Humanoid")
    if not hum then return end
    
    targetName = (targetName and targetName ~= "") and targetName or "Auto / Best"
    
    -- Check if character ALREADY has the requested combat weapon equipped
    local currentTool = char:FindFirstChildWhichIsA("Tool")
    if currentTool and isCombatTool(currentTool) then
        local currentBase = getBaseToolName(currentTool.Name):lower()
        if targetName == "Auto / Best" or targetName == "Any" then
            return -- Already holding a valid combat weapon! DO NOT SPAM
        end
        if currentBase == targetName:lower() or currentTool.Name:lower():find(targetName:lower(), 1, true) then
            return -- Already holding the exact weapon! DO NOT SPAM
        end
    end
    
    local bp = LocalPlayer:FindFirstChild("Backpack")
    if not bp then return end
    
    local candidate = nil
    -- Try to find the specific requested weapon first
    if targetName ~= "Auto / Best" and targetName ~= "Any" then
        for _, t in ipairs(bp:GetChildren()) do
            if isCombatTool(t) then
                local base = getBaseToolName(t.Name):lower()
                if base == targetName:lower() or t.Name:lower():find(targetName:lower(), 1, true) then
                    candidate = t
                    break
                end
            end
        end
    end
    
    -- Fall back to best combat weapon (Blades/Swords over Fist)
    if not candidate then
        local bestNonFist = nil
        local fistTool = nil
        for _, t in ipairs(bp:GetChildren()) do
            if isCombatTool(t) then
                local base = getBaseToolName(t.Name):lower()
                if base:find("fist") then
                    fistTool = t
                else
                    bestNonFist = t
                    break
                end
            end
        end
        candidate = bestNonFist or fistTool
    end
    
    if candidate then
        hum:EquipTool(candidate)
    end
end

