local function getNPCLocation(npcName, fallbackPos)
    local npcs = WS:FindFirstChild("NPCS")
    if npcs then
        local npc = npcs:FindFirstChild(npcName)
        if npc and npc:FindFirstChild("HumanoidRootPart") then
            return npc.HumanoidRootPart.Position, npc
        end
        for _, c in ipairs(npcs:GetChildren()) do
            if c.Name:lower():find(npcName:lower()) and c:FindFirstChild("HumanoidRootPart") then
                return c.HumanoidRootPart.Position, c
            end
        end
    end
    return fallbackPos or Vector3.new(0, 100, 0), nil
end

