-- Auto Harvest Minigame Critical Solver (Zero-Delay, 100% Perfect Cut)
local HarvestRingsRemote = Remotes and Remotes:FindFirstChild("HarvestRings")
if HarvestRingsRemote then
    HarvestRingsRemote.OnClientEvent:Connect(function(action, data)
        if not Hub.Alive then return end
        if action == "Ring" and typeof(data) == "table" and data.Id then
            task.spawn(function()
                local travel = data.Travel or 0.8
                local startTime = data.StartTime or workspace:GetServerTimeNow()
                local targetTime = startTime + travel
                while workspace:GetServerTimeNow() < targetTime and Hub.Alive do
                    task.wait()
                end
                local spin = data.Spin or 0
                local gapCenter = data.GapCenter or 0
                local angle = (gapCenter + (spin * travel)) % 360
                HarvestRingsRemote:FireServer("Report", data.Id, angle, workspace:GetServerTimeNow())
            end)
        end
    end)
end

local function findMatchingMob(mobName)
    local fightable = WS:FindFirstChild("FightableNPCS")
    if not fightable then return nil end
    local char = LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    if not hrp then return nil end

    local best = nil
    local minDist = math.huge
    for _, mob in ipairs(fightable:GetChildren()) do
        local hum = mob:FindFirstChildOfClass("Humanoid")
        local mHrp = mob:FindFirstChild("HumanoidRootPart")
        if hum and hum.Health > 0 and mHrp then
            local matches = (mob.Name == mobName) or (mobName:lower():find(mob.Name:lower())) or (mob.Name:lower():find(mobName:lower()))
            if matches then
                local d = (mHrp.Position - hrp.Position).Magnitude
                if d < minDist then
                    minDist = d
                    best = mob
                end
            end
        end
    end
    return best
end

-- UNKICKABLE GHOST FLY (Zero-Velocity CFrame + Broom State Bypass)
local moveConn = RunService.RenderStepped:Connect(function(dt)
    if not Hub.Alive then return end
    local char = LocalPlayer.Character
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    local hum = char and char:FindFirstChildOfClass("Humanoid")

    if hum and Hub.Flags.SpeedHack then
        hum.WalkSpeed = Hub.Flags.WalkSpeed
    end

    if hrp and hum and Hub.Flags.Fly then
        ensureBroomMountState()

        -- Bloquer detection Freefall
        hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, false)
        hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false)
        pcall(function() hum:ChangeState(Enum.HumanoidStateType.Swimming) end)

        -- Velocite physique a zero absolu (Anti-Detection Anticheat)
        hrp.Velocity = Vector3.new(0, 0, 0)
        hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
        hrp.AssemblyAngularVelocity = Vector3.new(0, 0, 0)

        local cam = WS.CurrentCamera
        local moveDir = Vector3.new(0, 0, 0)
        if UserInputService:IsKeyDown(Enum.KeyCode.W) then moveDir = moveDir + cam.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.S) then moveDir = moveDir - cam.CFrame.LookVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.A) then moveDir = moveDir - cam.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.D) then moveDir = moveDir + cam.CFrame.RightVector end
        if UserInputService:IsKeyDown(Enum.KeyCode.Space) then moveDir = moveDir + Vector3.new(0, 1, 0) end
        if UserInputService:IsKeyDown(Enum.KeyCode.LeftControl) then moveDir = moveDir - Vector3.new(0, 1, 0) end

        if moveDir.Magnitude > 0 then
            moveDir = moveDir.Unit
            local speed = Hub.Flags.FlySpeed or 65
            -- Solid character collision preserved (no wall clipping)
            hrp.CFrame = hrp.CFrame + (moveDir * (speed * math.clamp(dt, 0.005, 0.05)))
        end
    else
        if hum then
            hum:SetStateEnabled(Enum.HumanoidStateType.Freefall, true)
            hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true)
        end
    end

    -- Anti Void & Anti Fling
    if hrp and Hub.Flags.AntiVoid and hrp.Position.Y < -400 then
        hrp.Velocity = Vector3.new(0, 0, 0)
        hrp.CFrame = CFrame.new(hrp.Position.X, 150, hrp.Position.Z)
    end
    if hrp and Hub.Flags.AntiFling and hrp.AssemblyLinearVelocity.Magnitude > 150 then
        hrp.AssemblyLinearVelocity = Vector3.new(0, 0, 0)
    end

    -- Spinbot
    if hrp and Hub.Flags.Spinbot then
        hrp.CFrame = hrp.CFrame * CFrame.Angles(0, math.rad(Hub.Flags.SpinSpeed), 0)
    end
end)
table.insert(Hub.Connections, moveConn)

