local lvlLabel = StatsGroup:AddButton("Level: Loading...", { Icon = "user", Callback = function() end })
local marksLabel = StatsGroup:AddButton("Marks: Loading...", { Icon = "coins", Callback = function() end })
local xpLabel = StatsGroup:AddButton("XP: Loading...", { Icon = "award", Callback = function() end })
local magicLabel = StatsGroup:AddButton("Magic: Loading...", { Icon = "sparkles", Callback = function() end })
local rankLabel = StatsGroup:AddButton("Rank: Loading...", { Icon = "shield", Callback = function() end })
local weightLabel = StatsGroup:AddButton("Carry Weight: 0 / 100", { Icon = "package", Callback = function() end })

local timeLabel = RunGroup:AddButton("Running Time: 0s", { Icon = "clock", Callback = function() end })
local killsLabel = RunGroup:AddButton("Session Kills: 0", { Icon = "crosshair", Callback = function() end })
local itemsLabel = RunGroup:AddButton("Gathered Items: 0", { Icon = "archive", Callback = function() end })

local function getStatManager()
    if StatManager then return StatManager end
    local ok, res = pcall(function()
        local m = RS:FindFirstChild("Modules")
        local sm = m and m:FindFirstChild("StatManager")
        return sm and require(sm)
    end)
    if ok and res then
        StatManager = res
        return StatManager
    end
    return nil
end

task.spawn(function()
    while Hub.Alive do
        local elapsed = math.floor(os.clock() - Hub.StartTime)
        timeLabel:SetText(string.format("Running Time: %ds", elapsed))
        killsLabel:SetText(string.format("Session Kills: %d", Hub.RunStats.Kills))
        itemsLabel:SetText(string.format("Gathered Items: %d", Hub.RunStats.ItemsGathered))
        
        local smModule = getStatManager()
        if smModule then
            pcall(function()
                local sm = smModule.require(LocalPlayer)
                if sm then
                    local lvl = sm:GetStat("Level") or 1
                    local marks = sm:GetStat("Marks") or 0
                    local xp = sm:GetStat("XP") or 0
                    local magic = sm:GetStat("Magic") or "None"
                    local rank = sm:GetStat("Rank") or "No Rank"
                    local bonusW = sm:GetStat("BonusCarryWeight") or 0
                    local curW = sm:GetStat("CarryWeight") or 0
                    
                    lvlLabel:SetText(string.format("Level: %s", tostring(lvl)))
                    marksLabel:SetText(string.format("Marks: %s", tostring(marks)))
                    xpLabel:SetText(string.format("XP: %s", tostring(xp)))
                    magicLabel:SetText(string.format("Magic: %s", tostring(magic)))
                    rankLabel:SetText(string.format("Rank: %s", tostring(rank)))
                    weightLabel:SetText(string.format("Carry Weight: %s / %s", tostring(curW), tostring(100 + tonumber(bonusW or 0))))
                end
            end)
        end
        task.wait(1.5)
    end
end)

